        if(ad_low(rd_mux_addr) == ad_low(16'h1044)) begin
            readback_data_var[ad_hi(16'h1044)][31:0] = hwif_in.STRATEGY.RULE_FIRED_0.HI.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h1048)) begin
            readback_data_var[ad_hi(16'h1048)][31:0] = hwif_in.STRATEGY.RULE_FIRED_1.LO.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h104c)) begin
            readback_data_var[ad_hi(16'h104c)][31:0] = hwif_in.STRATEGY.RULE_FIRED_1.HI.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h1050)) begin
            readback_data_var[ad_hi(16'h1050)][31:0] = hwif_in.STRATEGY.RULE_FIRED_2.LO.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h1054)) begin
            readback_data_var[ad_hi(16'h1054)][31:0] = hwif_in.STRATEGY.RULE_FIRED_2.HI.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h1058)) begin
            readback_data_var[ad_hi(16'h1058)][31:0] = hwif_in.STRATEGY.RULE_FIRED_3.LO.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h105c)) begin
            readback_data_var[ad_hi(16'h105c)][31:0] = hwif_in.STRATEGY.RULE_FIRED_3.HI.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h1060)) begin
            readback_data_var[ad_hi(16'h1060)][31:0] = hwif_in.STRATEGY.RULE_FIRED_4.LO.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h1064)) begin
            readback_data_var[ad_hi(16'h1064)][31:0] = hwif_in.STRATEGY.RULE_FIRED_4.HI.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h1068)) begin
            readback_data_var[ad_hi(16'h1068)][31:0] = hwif_in.STRATEGY.RULE_FIRED_5.LO.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h106c)) begin
            readback_data_var[ad_hi(16'h106c)][31:0] = hwif_in.STRATEGY.RULE_FIRED_5.HI.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h1070)) begin
            readback_data_var[ad_hi(16'h1070)][31:0] = hwif_in.STRATEGY.RULE_FIRED_6.LO.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h1074)) begin
            readback_data_var[ad_hi(16'h1074)][31:0] = hwif_in.STRATEGY.RULE_FIRED_6.HI.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h1078)) begin
            readback_data_var[ad_hi(16'h1078)][31:0] = hwif_in.STRATEGY.RULE_FIRED_7.LO.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h107c)) begin
            readback_data_var[ad_hi(16'h107c)][31:0] = hwif_in.STRATEGY.RULE_FIRED_7.HI.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2000)) begin
            readback_data_var[ad_hi(16'h2000)][0] = field_storage.TX.TX_CTRL.tx_en.value;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2004)) begin
            readback_data_var[ad_hi(16'h2004)][7:0] = field_storage.TX.TX_OUCH.display.value;
            readback_data_var[ad_hi(16'h2004)][15:8] = field_storage.TX.TX_OUCH.capacity.value;
            readback_data_var[ad_hi(16'h2004)][23:16] = field_storage.TX.TX_OUCH.ise.value;
            readback_data_var[ad_hi(16'h2004)][31:24] = field_storage.TX.TX_OUCH.cross_type.value;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h200c)) begin
            readback_data_var[ad_hi(16'h200c)][0] = hwif_in.TX.TX_STATUS.cfg_valid.next;
            readback_data_var[ad_hi(16'h200c)][1] = hwif_in.TX.TX_STATUS.cfg_refused.next;
            readback_data_var[ad_hi(16'h200c)][2] = hwif_in.TX.TX_STATUS.userref_ignored.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2014)) begin
            readback_data_var[ad_hi(16'h2014)] = hwif_in.TX.TX_USERREF.rd_data;
        end
        for(int i0=0; i0<10; i0++) begin
            if(ad_low(rd_mux_addr) == ad_low(16'h2020 + (16)'(i0) * 16'h4)) begin
                readback_data_var[ad_hi(16'h2020 + (16)'(i0) * 16'h4)][31:0] = field_storage.TX.TX_TEMPLATE[i0].bytes.value;
            end
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2048)) begin
            readback_data_var[ad_hi(16'h2048)][31:16] = field_storage.TX.TX_TEMPLATE_TAIL.bytes.value;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2050)) begin
            readback_data_var[ad_hi(16'h2050)][7:0] = field_storage.TX.MBOX_SIDE.side.value;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2054)) begin
            readback_data_var[ad_hi(16'h2054)][31:0] = field_storage.TX.MBOX_QTY.qty.value;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2058)) begin
            readback_data_var[ad_hi(16'h2058)][31:0] = field_storage.TX.MBOX_PRICE.price.value;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h205c)) begin
            readback_data_var[ad_hi(16'h205c)][15:0] = field_storage.TX.MBOX_LOCATE.locate.value;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2060)) begin
            readback_data_var[ad_hi(16'h2060)][31:0] = field_storage.TX.MBOX_STOCK_0.bytes.value;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2064)) begin
            readback_data_var[ad_hi(16'h2064)][31:0] = field_storage.TX.MBOX_STOCK_1.bytes.value;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2068)) begin
            readback_data_var[ad_hi(16'h2068)][7:0] = field_storage.TX.MBOX_TIF.tif.value;
        end
        for(int i0=0; i0<3; i0++) begin
            if(ad_low(rd_mux_addr) == ad_low(16'h2070 + (16)'(i0) * 16'h4)) begin
                readback_data_var[ad_hi(16'h2070 + (16)'(i0) * 16'h4)][31:0] = field_storage.TX.MBOX_CLORDID[i0].bytes.value;
            end
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h207c)) begin
            readback_data_var[ad_hi(16'h207c)][31:16] = field_storage.TX.MBOX_CLORDID_TAIL.bytes.value;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2084)) begin
            readback_data_var[ad_hi(16'h2084)][4:0] = hwif_in.TX.MBOX_SPACE.space.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2088)) begin
            readback_data_var[ad_hi(16'h2088)][0] = hwif_in.TX.MBOX_STATUS.dropped.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2090)) begin
            readback_data_var[ad_hi(16'h2090)][31:0] = hwif_in.TX.MBOX_DROP.LO.value.next;
        end
        if(ad_low(rd_mux_addr) == ad_low(16'h2094)) begin
            readback_data_var[ad_hi(16'h2094)][31:0] = hwif_in.TX.MBOX_DROP.HI.value.next;
        end
        readback_data_rt_c = readback_data_var;
    end

    logic [31:0] readback_data_rt[128];
    logic readback_done_rt;
    logic readback_err_rt;
    logic [15:0] readback_addr_rt;
    always_ff @(posedge clk) begin
        if(rst) begin
            for(int i=0; i<128; i++) readback_data_rt[i] <= '0;
            readback_done_rt <= '0;
            readback_err_rt <= '0;
            readback_addr_rt <= '0;
        end else begin
            readback_data_rt <= readback_data_rt_c;
            readback_err_rt <= decoded_err;
            readback_done_rt <= decoded_req & ~decoded_req_is_wr & ~decoded_req_is_external;
            readback_addr_rt <= rd_mux_addr;
        end
    end



    // readback stage 2
    always_comb begin
        readback_data = readback_data_rt[readback_addr_rt[15:9]];
        readback_done = readback_done_rt;
        readback_err = readback_err_rt;
    end

    assign external_rd_ack = readback_external_rd_ack;
    assign cpuif_rd_ack = readback_done | readback_external_rd_ack;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
